  classification_confidence, review_status, updated_at
)
select
  item->>'sourceCategory',
  item->>'beneficiaryCat',
  item->>'mappingBasis',
  (item->>'confidence')::numeric,
  item->>'reviewStatus',
  now()
from jsonb_array_elements($beneficiary_source_map$[{"sourceCategory":"연기금","beneficiaryCat":"연기금·공공기금","beneficiaryClass":"기관","mappingBasis":"기존 원천분류 연기금의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"공제회","beneficiaryCat":"공제회","beneficiaryClass":"기관","mappingBasis":"기존 원천분류 공제회의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"정부기관","beneficiaryCat":"정부·공공기관","beneficiaryClass":"기관","mappingBasis":"기존 원천분류 정부기관의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"조합","beneficiaryCat":"협동조합·중앙회","beneficiaryClass":"기관","mappingBasis":"기존 원천분류 조합의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"기타 투자기관","beneficiaryCat":"기타기관","beneficiaryClass":"기관","mappingBasis":"기존 원천분류 기타 투자기관의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"은행","beneficiaryCat":"은행","beneficiaryClass":"금융기관","mappingBasis":"기존 원천분류 은행의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"보험사","beneficiaryCat":"보험사","beneficiaryClass":"금융기관","mappingBasis":"기존 원천분류 보험사의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"증권사","beneficiaryCat":"증권사","beneficiaryClass":"금융기관","mappingBasis":"기존 원천분류 증권사의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"자산운용사","beneficiaryCat":"자산운용사","beneficiaryClass":"금융기관","mappingBasis":"기존 원천분류 자산운용사의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"리스사","beneficiaryCat":"캐피탈·리스사","beneficiaryClass":"금융기관","mappingBasis":"기존 원천분류 리스사의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"상호 저축은행 및 기타 저축기관","beneficiaryCat":"저축은행","beneficiaryClass":"금융기관","mappingBasis":"기존 원천분류 상호 저축은행 및 기타 저축기관의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"신용카드 및 할부금융업","beneficiaryCat":"카드·할부금융","beneficiaryClass":"금융기관","mappingBasis":"기존 원천분류 신용카드 및 할부금융업의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"여신금융업","beneficiaryCat":"캐피탈·리스사","beneficiaryClass":"금융기관","mappingBasis":"기존 원천분류 여신금융업의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"종합금융회사","beneficiaryCat":"종합금융회사","beneficiaryClass":"금융기관","mappingBasis":"기존 원천분류 종합금융회사의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"금융투자업","beneficiaryCat":"기타금융기관","beneficiaryClass":"금융기관","mappingBasis":"기존 원천분류 금융투자업의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"일반기업","beneficiaryCat":"일반기업","beneficiaryClass":"일반기업","mappingBasis":"기존 원천분류 일반기업의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"개인","beneficiaryCat":"개인","beneficiaryClass":"개인","mappingBasis":"기존 원천분류 개인의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"펀드","beneficiaryCat":"펀드","beneficiaryClass":"펀드·리츠·SPC","mappingBasis":"기존 원천분류 펀드의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"상장공모리츠","beneficiaryCat":"리츠","beneficiaryClass":"펀드·리츠·SPC","mappingBasis":"기존 원천분류 상장공모리츠의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"사모리츠","beneficiaryCat":"리츠","beneficiaryClass":"펀드·리츠·SPC","mappingBasis":"기존 원천분류 사모리츠의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"SPC","beneficiaryCat":"SPC","beneficiaryClass":"펀드·리츠·SPC","mappingBasis":"기존 원천분류 SPC의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"비공개","beneficiaryCat":"비공개","beneficiaryClass":"미분류","mappingBasis":"기존 원천분류 비공개의 통제분류 매핑","confidence":0.9,"reviewStatus":"confirmed"},{"sourceCategory":"기타","beneficiaryCat":"미분류","beneficiaryClass":"미분류","mappingBasis":"기타는 기관 성격이 아니므로 명칭별 검토 필요","confidence":0,"reviewStatus":"review"},{"sourceCategory":"고유","beneficiaryCat":"미분류","beneficiaryClass":"미분류","mappingBasis":"고유는 기관 성격이 아니므로 명칭별 검토 필요","confidence":0,"reviewStatus":"review"},{"sourceCategory":"미분류","beneficiaryCat":"미분류","beneficiaryClass":"미분류","mappingBasis":"미분류는 기관 성격이 아니므로 명칭별 검토 필요","confidence":0,"reviewStatus":"review"}]$beneficiary_source_map$::jsonb) as item
on conflict (source_category) do update set
